(function(){
  const pools={
    weight_loss:{full:[['Goblet Squat','Chest Press','Lat Pulldown','مشي سريع'],['Leg Press','Push Up','Seated Row','دراجة'],['Box Squat','Cable Row','Shoulder Press','مشي مائل']],lower:[['Leg Press','Hip Thrust','Leg Curl','مشي سريع'],['Goblet Squat','Glute Bridge','Step Up','دراجة'],['Box Squat','Cable Pull Through','Seated Leg Curl','مشي مائل']],upper:[['Chest Press','Lat Pulldown','Shoulder Press','Biceps Curl'],['Push Up','Seated Row','Chest Fly','Triceps Pushdown'],['Cable Row','Incline Chest Press','Face Pull','Hammer Curl']]},
    muscle_gain:{push:[['Bench Press','Shoulder Press','Chest Fly','Triceps Pushdown'],['Incline Chest Press','Machine Shoulder Press','Cable Fly','Overhead Triceps Extension'],['Chest Press','Lateral Raise','Push Up','Rope Pushdown']],pull:[['Lat Pulldown','Seated Row','Face Pull','Biceps Curl'],['Cable Row','Neutral Grip Pulldown','Reverse Fly','Hammer Curl'],['Assisted Pull Up','One Arm Cable Row','Rear Delt Fly','Cable Curl']],legs:[['Squat','Leg Press','Hip Thrust','Leg Curl'],['Goblet Squat','Romanian Deadlift','Step Up','Calf Raise'],['Hack Squat','Glute Bridge','Seated Leg Curl','Leg Extension']]},
    fitness:{full:[['Goblet Squat','Push Up','Cable Row','Plank'],['Leg Press','Chest Press','Lat Pulldown','Dead Bug'],['Step Up','Shoulder Press','Seated Row','Bird Dog']],conditioning:[['مشي سريع','Lunges','Battle Rope','تمارين مرونة'],['دراجة','Step Up','Medicine Ball','Plank'],['مشي مائل','Box Squat','Cable Row','تمارين مرونة']],strength:[['Leg Press','Chest Press','Lat Pulldown','دراجة'],['Goblet Squat','Shoulder Press','Seated Row','مشي سريع'],['Hip Thrust','Push Up','Cable Row','تمارين مرونة']]}
  };
  const safer={knee:{'Squat':'Box Squat','Goblet Squat':'Box Squat','Lunges':'Glute Bridge','Step Up':'Glute Bridge','Leg Press':'Hip Thrust','Hack Squat':'Glute Bridge','مشي مائل':'دراجة'},back:{'Squat':'Leg Press','Goblet Squat':'Leg Press','Romanian Deadlift':'Seated Leg Curl','Cable Pull Through':'Glute Bridge','Plank':'Dead Bug'},shoulder:{'Shoulder Press':'Lateral Raise','Machine Shoulder Press':'Lateral Raise','Bench Press':'Chest Press','Push Up':'Chest Press','Incline Chest Press':'Chest Press','Battle Rope':'دراجة'},cardio:{'مشي سريع':'مشي خفيف','مشي مائل':'مشي خفيف','Battle Rope':'دراجة خفيفة','Lunges':'Glute Bridge'}};
  const labels={beginner:'مبتدئ',intermediate:'متوسط',advanced:'متقدم',none:'لا توجد',knee:'الركبة',back:'الظهر',shoulder:'الكتف',cardio:'لياقة منخفضة'};
  function hash(value){let h=2166136261;for(const c of String(value)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
  function ageFrom(date){if(!date)return 25;const born=new Date(date+'T00:00:00'),now=new Date();let age=now.getFullYear()-born.getFullYear();if(now<new Date(now.getFullYear(),born.getMonth(),born.getDate()))age--;return Math.max(14,Math.min(90,age||25))}
  function prescription(level,goal,limited){const reps=goal==='muscle_gain'?(level==='advanced'?'4×6–10':level==='intermediate'?'4×8–12':'3×10–12'):(level==='advanced'?'4×10–15':'3×12–15');return limited&&level==='advanced'?'3×10–12':reps}
  function applyLimit(exercises,limit){const map=safer[limit]||{};return exercises.map(name=>map[name]||name)}
  function uniquePick(options,seed,used){for(let i=0;i<options.length;i++){const pick=options[(seed+i)%options.length];if(!used.has(pick.join('|'))){used.add(pick.join('|'));return pick}}return options[seed%options.length]}
  function build({member,measurement,health,logs=[],goal,days,notes,level='beginner',limitation='none'}){
    const weight=Number(measurement?.weight_kg||70),height=Number(measurement?.height_cm||165),age=ageFrom(health?.birth_date),activity={low:1.3,moderate:1.45,high:1.6}[health?.activity_level]||1.45;
    const base=10*weight+6.25*height-5*age+(member?.gender==='male'?5:-161),calories=Math.max(1200,Math.round((base*activity+(goal==='muscle_gain'?250:goal==='weight_loss'?-350:0))/50)*50),protein=Math.round(weight*(goal==='muscle_gain'?2:1.7)),fats=Math.round(weight*.8),carbs=Math.max(80,Math.round((calories-protein*4-fats*9)/4)),water=Math.min(8,Math.max(1.5,Math.round(weight*.035*10)/10));
    const seed=hash(member?.id||member?.email||'strong-gym'),completed=logs.filter(x=>x.completed),hardRate=completed.length?completed.filter(x=>x.difficulty==='hard').length/completed.length:0;
    let effectiveLevel=level;if(hardRate>.55)effectiveLevel='beginner';else if(completed.length>=12&&hardRate<.2&&level==='beginner')effectiveLevel='intermediate';
    const splits=goal==='muscle_gain'?['push','pull','legs']:goal==='weight_loss'?['full','lower','upper']:['full','conditioning','strength'],used=new Set(),workout=[];
    for(let i=0;i<Number(days);i++){const split=splits[i%splits.length],choices=pools[goal][split],memberVariant=(seed>>>((i*7)%24))%choices.length,chosen=uniquePick(choices,memberVariant,used),adapted=applyLimit(chosen,limitation),rx=prescription(effectiveLevel,goal,limitation!=='none');workout.push({day:`اليوم ${i+1}`,focus:{push:'دفع',pull:'سحب',legs:'أرجل',full:'جسم كامل',lower:'جزء سفلي',upper:'جزء علوي',conditioning:'لياقة وحركة',strength:'قوة وظيفية'}[split],exercises:adapted.map((name,index)=>/مشي|دراجة|مرونة/.test(name)?`${name} ${effectiveLevel==='beginner'?15:effectiveLevel==='advanced'?30:20} دقيقة`:`${name} ${index===3&&goal!=='muscle_gain'?'3×30 ثانية':rx}`)});}
    const meals=[{name:'الإفطار',items:'بيض أو لبنة + خبز كامل + خضار'},{name:'وجبة خفيفة',items:'فاكهة + حفنة مكسرات'},{name:'الغداء',items:'مصدر بروتين + أرز أو بطاطا + سلطة'},{name:'بعد التمرين',items:'زبادي أو حليب + موز'},{name:'العشاء',items:'تونة أو جبنة قليلة الدسم + خضار'}],context=`مستوى: ${labels[effectiveLevel]} · مراعاة: ${labels[limitation]}. ${notes||health?.medical_notes||''}`.trim();
    return{member_id:member.id,goal,training_days:Number(days),daily_calories:calories,protein_g:protein,carbs_g:carbs,fats_g:fats,water_liters:water,workout_plan:workout,meal_plan:meals,notes:context,active:true};
  }
  window.StrongGymPersonalizer={build};
})();
